llm:
// ⚠️ 자동 생성 파일 — 직접 수정하지 마세요.
// 원본: supabase/functions/_shared/llm.ts · 갱신: npm run sync:fn
/**
 * LLM 제공자 어댑터 — Anthropic Claude / Google Gemini 중 설정된 쪽으로 호출한다.
 *
 * 왜 필요한가: 세 엣지 함수(deep-report·ai-report·fortune-detail)가 각자 fetch를 직접 짜고 있어서
 * 제공자를 바꾸려면 세 군데를 고쳐야 했다. 무료 티어(Gemini)로 운영하다가 품질이 필요할 때
 * Anthropic으로 되돌리는 전환이 시크릿 하나로 끝나야 한다.
 *
 * 시크릿(둘 중 하나만 있어도 동작):
 *   ANTHROPIC_API_KEY          → Claude 사용 (모델: AI_MODEL, 기본 claude-opus-5)
 *   GOOGLE_API_KEY 또는 GEMINI_API_KEY → Gemini 사용 (모델: GEMINI_MODEL, 기본 gemini-3.7-flash)
 *   LLM_PROVIDER=anthropic|google      → 둘 다 넣었을 때 강제 지정(미지정 시 Anthropic 우선)
 *
 * ⚠️ 이 파일은 supabase/functions/_shared/llm.ts 가 원본이다.
 *    각 함수 폴더의 llm.ts는 `npm run sync:fn` 이 만드는 사본 — 직접 고치지 말 것(스모크가 동일성을 검사한다).
 */

export type Provider = 'anthropic' | 'google'

export interface LlmOptions {
  /**
   * 출력 토큰 예산.
   * ⚠️ 두 제공자 모두 '생각(thinking)' 토큰이 이 예산에서 나간다 — Claude Opus 5는 thinking이 기본 ON,
   *    Gemini 3.x flash도 내부 추론을 쓴다. 원하는 본문 길이의 3~5배를 주지 않으면 조용히 잘린다.
   */
  maxTokens: number
  /** 응답을 JSON으로만 받고 싶을 때. Gemini는 responseMimeType으로 강제, Claude는 프롬프트 규약에 의존. */
  json?: boolean
  /** Anthropic 전용 추론 강도(Gemini에는 대응 파라미터가 없어 무시된다) */
  effort?: 'low' | 'medium' | 'high'
}

export interface LlmResult {
  ok: boolean
  text?: string
  /** no_key | upstream | truncated | refusal | empty — 원인마다 대응이 달라 뭉뚱그리지 않는다 */
  error?: string
  detail?: string
  provider?: Provider
  model?: string
}

function env(k: string): string {
  // @ts-ignore Deno 런타임 전역
  return (Deno.env.get(k) ?? '').trim()
}

/** 설정된 시크릿으로 제공자를 결정한다. 아무 키도 없으면 null. */
export function resolveProvider(): { provider: Provider; key: string; model: string } | null {
  const googleKey = env('GOOGLE_API_KEY') || env('GEMINI_API_KEY')
  const anthropicKey = env('ANTHROPIC_API_KEY')
  const forced = env('LLM_PROVIDER').toLowerCase()

  const wantGoogle = forced === 'google' || forced === 'gemini'
  const wantAnthropic = forced === 'anthropic' || forced === 'claude'

  if (wantGoogle && googleKey) return { provider: 'google', key: googleKey, model: env('GEMINI_MODEL') || 'gemini-3.7-flash' }
  if (wantAnthropic && anthropicKey) return { provider: 'anthropic', key: anthropicKey, model: env('AI_MODEL') || 'claude-opus-5' }
  // 명시 지정이 없으면: 둘 다 있을 때 Anthropic 우선(품질 기본값). 진단 화면이 실제 선택을 보여준다.
  if (anthropicKey) return { provider: 'anthropic', key: anthropicKey, model: env('AI_MODEL') || 'claude-opus-5' }
  if (googleKey) return { provider: 'google', key: googleKey, model: env('GEMINI_MODEL') || 'gemini-3.7-flash' }
  return null
}

async function callAnthropic(
  key: string,
  model: string,
  system: string,
  user: string,
  opt: LlmOptions,
): Promise<LlmResult> {
  const base = { provider: 'anthropic' as const, model }
  const body: Record<string, unknown> = {
    model,
    max_tokens: opt.maxTokens,
    system,
    messages: [{ role: 'user', content: user }],
  }
  // effort는 Claude 4.6+ 계열에만 있다. Haiku 4.5 등 구형 모델에 보내면 요청 자체가 거부되므로
  // 모델명으로 걸러 낸다("절대 넣지 말 것"을 주석이 아니라 코드로 강제).
  if (opt.effort && !/haiku|claude-3|sonnet-4-5/.test(model)) body.output_config = { effort: opt.effort }

  const resp = await fetch('https://api.anthropic.com/v1/messages', {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify(body),
  })
  if (!resp.ok) {
    // 상류 오류 본문을 그대로 넘긴다 — 키 오타/크레딧 소진/모델명 오류를 구분할 유일한 단서.
    // (상류는 API 키를 에코하지 않으므로 이 본문에 키가 들어가지 않는다.)
    const why = await resp.text().catch(() => '')
    return { ...base, ok: false, error: 'upstream', detail: `${resp.status}: ${why.slice(0, 300)}` }
  }
  const data = await resp.json()
  // 안전 차단은 HTTP 200으로 온다 — content를 읽기 전에 stop_reason부터 본다
  if (data.stop_reason === 'refusal') return { ...base, ok: false, error: 'refusal' }
  // thinking 블록이 섞여 오므로 text 블록만 취한다(합치면 JSON 앞에 요약문이 붙어 파싱이 깨진다)
  const text = (data.content ?? [])
    .filter((c: { type?: string }) => c.type === 'text')
    .map((c: { text?: string }) => c.text ?? '')
    .join('')
    .trim()
  if (!text) return { ...base, ok: false, error: 'empty' }
  if (data.stop_reason === 'max_tokens') return { ...base, ok: false, error: 'truncated' }
  return { ...base, ok: true, text }
}

async function callGoogle(
  key: string,
  model: string,
  system: string,
  user: string,
  opt: LlmOptions,
): Promise<LlmResult> {
  const base = { provider: 'google' as const, model }
  const generationConfig: Record<string, unknown> = { maxOutputTokens: opt.maxTokens }
  // Gemini는 JSON 출력을 형식 수준에서 강제할 수 있다 — 코드펜스 방어 파싱이 아예 필요 없어진다
  if (opt.json) generationConfig.responseMimeType = 'application/json'

  const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, {
    method: 'POST',
    // 키는 헤더로 — ?key= 쿼리 파라미터는 접근 로그·리퍼러에 그대로 남는다
    headers: { 'content-type': 'application/json', 'x-goog-api-key': key },
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig,
    }),
  })
  if (!resp.ok) {
    const why = await resp.text().catch(() => '')
    return { ...base, ok: false, error: 'upstream', detail: `${resp.status}: ${why.slice(0, 300)}` }
  }
  const data = await resp.json()
  // 프롬프트 단계 차단은 candidates 자체가 비어서 온다 — 아래 'empty'와 구분해 사유를 남긴다
  const blocked = data.promptFeedback?.blockReason
  if (blocked) return { ...base, ok: false, error: 'refusal', detail: `promptFeedback=${blocked}` }

  const cand = (data.candidates ?? [])[0]
  const finish = cand?.finishReason
  if (finish && ['SAFETY', 'PROHIBITED_CONTENT', 'BLOCKLIST', 'RECITATION'].includes(finish)) {
    return { ...base, ok: false, error: 'refusal', detail: `finishReason=${finish}` }
  }
  const text = ((cand?.content?.parts ?? []) as { text?: string }[])
    .map((p) => p.text ?? '')
    .join('')
    .trim()
  if (!text) return { ...base, ok: false, error: 'empty', detail: finish ? `finishReason=${finish}` : undefined }
  // MAX_TOKENS는 본문이 일부 있어도 잘린 것 — parse 실패로 뭉뚱그리면 원인 추적이 불가능해진다
  if (finish === 'MAX_TOKENS') return { ...base, ok: false, error: 'truncated' }
  return { ...base, ok: true, text }
}

/** 설정된 제공자로 1회 호출. 실패 사유는 error 코드로 구조화해 돌려준다. */
export async function callLlm(system: string, user: string, opt: LlmOptions): Promise<LlmResult> {
  const r = resolveProvider()
  if (!r) return { ok: false, error: 'no_key' }
  try {
    return r.provider === 'google'
      ? await callGoogle(r.key, r.model, system, user, opt)
      : await callAnthropic(r.key, r.model, system, user, opt)
  } catch (e) {
    return { ok: false, error: 'network', detail: String(e).slice(0, 200), provider: r.provider, model: r.model }
  }
}

/** 모델이 코드펜스를 붙이거나 앞뒤에 설명을 덧대는 경우까지 방어적으로 JSON을 뽑는다. */
export function parseJson<T>(text: string): T | null {
  const raw = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')
  try {
    return JSON.parse(raw) as T
  } catch {
    const a = raw.indexOf('{')
    const z = raw.lastIndexOf('}')
    if (a < 0 || z <= a) return null
    try {
      return JSON.parse(raw.slice(a, z + 1)) as T
    } catch {
      return null
    }
  }
}

ai-report:
/**
 * Supabase Edge Function — AI 정밀 분석 리포트 생성.
 *
 * 키는 서버(엣지)에만: 클라이언트에 노출되지 않습니다.
 * 제공자·모델 선택은 ./llm.ts — ANTHROPIC_API_KEY 또는 GOOGLE_API_KEY 중 설정된 쪽을 자동 사용.
 * 키 미설정 시 클라이언트가 기존 정적 리포트로 폴백하므로 앱은 그대로 동작합니다.
 */
import { callLlm } from './llm.ts'

const CORS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(o: unknown, status = 200): Response {
  return new Response(JSON.stringify(o), { status, headers: { ...CORS, 'content-type': 'application/json' } })
}

// @ts-ignore Deno 런타임 전역
Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  try {
    const b = await req.json()
    const lang: string = b.lang ?? 'ko'
    const langName = lang === 'en' ? 'English' : lang === 'ja' ? 'Japanese' : 'Korean'
    const join = (a: unknown): string => (Array.isArray(a) ? a.filter(Boolean).join(', ') : '')

    const system =
      `You are a warm but honest psychology coach. Write a 3-paragraph integrated interpretation in ${langName} based on a self-test result. ` +
      `No medical diagnosis or medication advice. Express tendencies, not fixed labels. Include empathy and ONE concrete small action. Keep it ~250 words.`
    const user =
      `Test: ${b.testName}\nBand: ${b.band} (top ${b.topPercent}%)\nPersona: ${b.persona}\n` +
      `Strengths: ${join(b.strengths)}\nWatch-outs: ${join(b.risks)}\nHelps: ${join(b.solutions)}\n\n` +
      `Write the warm, integrated 3-paragraph interpretation for this person.`

    const r = await callLlm(system, user, {
      // ⚠️ 생각 토큰이 이 예산에서 나간다 — 250단어 글에 800을 주면 생각하다 본문이 잘린다
      maxTokens: 4000,
      // 짧은 단일 검사 해설이라 낮은 추론 강도로 충분 — 지연·비용을 줄인다
      effort: 'low',
    })
    if (!r.ok || !r.text) return json({ error: r.error ?? 'empty', detail: r.detail, provider: r.provider, model: r.model }, r.error === 'no_key' ? 500 : 502)
    return json({ text: r.text, provider: r.provider, model: r.model })
  } catch (e) {
    return json({ error: String(e) }, 500)
  }
})

deep-report:
/**
 * Supabase Edge Function — AI 종합 심층 리포트 (프리미엄 전용).
 *
 * 개별 검사 리포트(ai-report)와 다른 점: 검사 하나를 해석하는 게 아니라
 * **전 검사를 가로질러 "한 사람"으로 통합**한다. 이것이 프리미엄의 유일한 가치.
 *
 * 키는 서버(엣지)에만 — 클라이언트에 노출되지 않습니다. 제공자·모델 선택은 ./llm.ts 참고
 * (ANTHROPIC_API_KEY 또는 GOOGLE_API_KEY 중 설정된 쪽을 자동 사용).
 * 미배포/키 없음 → 클라가 정적 폴백(페르소나 조합)으로 동작하므로 앱은 그대로.
 *
 * ⚠️ 프리미엄 판정은 현재 클라이언트 attested(구독 상태를 클라가 보냄).
 *    서버측 검증(profiles.premium_until 조회)은 하드닝 항목 — PG 연동 시 함께 적용.
 */
import { callLlm, parseJson } from './llm.ts'

const CORS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(o: unknown, status = 200): Response {
  return new Response(JSON.stringify(o), { status, headers: { ...CORS, 'content-type': 'application/json' } })
}

/** 리포트 섹션 키 — 클라 렌더 순서·아이콘과 1:1 대응(고정) */
const SECTION_KEYS = [
  'core',       // 핵심 성격 요약 (비프리미엄 티저로 노출되는 유일 섹션)
  'strengths',  // 타고난 강점
  'shadow',     // 그림자·취약 지점
  'relations',  // 관계 속의 나
  'work',       // 일·성취 스타일
  'stress',     // 스트레스·회복
  'cognition',  // 인지 프로필 (정밀검사 완료 시에만)
  'roadmap',    // 90일 성장 로드맵
] as const

interface TestSummary {
  name: string
  band: string
  topPercent: number
  persona: string
  strengths: string[]
  risks: string[]
  axes?: Record<string, number>
}

// @ts-ignore Deno 런타임 전역
Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  try {
    const b = await req.json()
    const lang: string = b.lang ?? 'ko'
    const langName = lang === 'en' ? 'English' : lang === 'ja' ? 'Japanese' : 'Korean'
    const tests: TestSummary[] = Array.isArray(b.tests) ? b.tests.slice(0, 20) : []
    if (tests.length < 3) return json({ error: 'not_enough_tests' }, 400)

    const nickname: string = String(b.nickname ?? '').slice(0, 20)
    const cog: Record<string, number> | null = b.cognition ?? null
    const hasCog = !!cog && Object.keys(cog).length > 0
    const keys = SECTION_KEYS.filter((k) => k !== 'cognition' || hasCog)

    const system =
      `You are a warm but honest psychology coach writing an integrated personal report in ${langName}. ` +
      `The reader completed MANY self-tests. Your ONE job: find the threads that run ACROSS tests and describe them as one whole person — ` +
      `never a test-by-test recap. Cite their actual numbers/bands as evidence when it helps. ` +
      `Rules: no medical diagnosis, no medication advice; describe tendencies, not fixed labels; ` +
      `warm and specific, never generic horoscope language; every section ends with one concrete, doable action. ` +
      `Output STRICT JSON only: {"sections":[{"key":"...","title":"...","body":"..."}]} with keys exactly [${keys.join(', ')}] in that order. ` +
      `title: short ${langName} heading. body: 2-3 paragraphs, plain text (no markdown). Total ~1800 characters across all sections.`

    const lines = tests
      .map(
        (t) =>
          `- ${t.name}: band=${t.band}, top ${t.topPercent}%, persona=${t.persona}` +
          (t.axes ? `, axes=${JSON.stringify(t.axes)}` : '') +
          (t.strengths?.length ? `, strengths=[${t.strengths.slice(0, 2).join(' / ')}]` : '') +
          (t.risks?.length ? `, watch=[${t.risks.slice(0, 2).join(' / ')}]` : ''),
      )
      .join('\n')

    const user =
      (nickname ? `Reader nickname: ${nickname}\n` : '') +
      `Completed tests (${tests.length}):\n${lines}\n` +
      (hasCog ? `Cognitive indices (100=avg, SD15): ${JSON.stringify(cog)}\n` : '') +
      `\nWrite the integrated report now. Remember: cross-test threads, not a per-test list.`

    const r = await callLlm(system, user, {
      // ⚠️ 생각 토큰이 이 예산에서 나간다 — 8섹션(~1800자) JSON을 4000으로 잡으면
      //    생각 도중 잘려 파싱에 실패하고, 사용자는 키를 넣었는데도 정적 폴백만 본다.
      maxTokens: 12000,
      json: true,
      // 화면이 '20초 정도'를 약속한다 — 리포트 작성은 medium이면 충분하다
      effort: 'medium',
    })
    if (!r.ok || !r.text) return json({ error: r.error ?? 'empty', detail: r.detail, provider: r.provider, model: r.model }, r.error === 'no_key' ? 500 : 502)

    // Gemini는 responseMimeType으로 JSON을 강제하지만 Claude는 프롬프트 규약에 의존하므로
    // 코드펜스·앞뒤 설명까지 방어적으로 파싱한다(제공자에 따라 응답 모양이 다르다).
    const parsed = parseJson<{ sections?: { key?: string; title?: string; body?: string }[] }>(r.text)
    if (!parsed) return json({ error: 'parse', provider: r.provider, model: r.model }, 502)

    const sections = (parsed.sections ?? [])
      .filter((s) => s && typeof s.body === 'string' && s.body.trim().length > 0)
      .map((s) => ({ key: String(s.key ?? ''), title: String(s.title ?? ''), body: String(s.body) }))
    if (sections.length < 3) return json({ error: 'thin', provider: r.provider, model: r.model }, 502)

    return json({ sections, at: Date.now(), provider: r.provider, model: r.model })
  } catch (e) {
    return json({ error: 'server', detail: String(e).slice(0, 200) }, 500)
  }
})

fortune-detail:
/**
 * Supabase Edge Function — 오늘의 '상세 운세' AI 개인화.
 *
 * 키는 서버(엣지)에만: 클라이언트에 노출되지 않습니다.
 * 제공자·모델 선택은 ./llm.ts — ANTHROPIC_API_KEY 또는 GOOGLE_API_KEY 중 설정된 쪽을 자동 사용.
 * 결과는 클라가 (생일+날짜) 기준 하루 1회만 호출·캐싱하고, 실패 시 결정론 템플릿으로 자동 폴백.
 *
 * ⚠️ 셋 중 호출량이 가장 많은 함수다 — 무료 티어(Gemini)나 저가 모델을 쓰고 싶다면 여기부터.
 *    GEMINI_MODEL / AI_MODEL 시크릿으로 이 함수만 따로 지정할 수는 없으니(공용 어댑터),
 *    비용이 문제라면 전체를 Gemini로 돌리는 편이 단순하다.
 */
import { callLlm, parseJson } from './llm.ts'

const CORS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}

function json(o: unknown, status = 200): Response {
  return new Response(JSON.stringify(o), { status, headers: { ...CORS, 'content-type': 'application/json' } })
}

const KEYS = ['morning', 'noon', 'evening', 'luckyTime', 'place', 'item', 'food', 'caution', 'advice', 'relation', 'work', 'wealth', 'health', 'summary']

// @ts-ignore Deno 런타임 전역
Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS })
  if (req.method !== 'POST') return json({ error: 'method' }, 405)
  try {
    const b = await req.json()
    const lang: string = b.lang ?? 'ko'
    const langName = lang === 'en' ? 'English' : lang === 'ja' ? 'Japanese' : 'Korean'

    const system =
      `You write a warm, playful Korean-style "today's fortune" (오늘의 운세) detail in ${langName}. ` +
      `Output STRICT JSON only (no markdown, no code fences) with EXACTLY these keys: ${KEYS.join(', ')}. ` +
      `Each value is a single natural sentence, EXCEPT: place/item/food are short noun phrases, luckyTime is a short time range, ` +
      `summary ends by stating a keyword in quotes. It is "just for fun" (재미로 보는 운세) — positive, specific, actionable. ` +
      `No fortune-telling certainty, no medical/financial advice, no scary predictions.`
    const user =
      `Person — day pillar(일주): ${b.ilju}, element(오행): ${b.element}, zodiac(띠): ${b.zodiac}. ` +
      `Today's lucky direction: ${b.luckyDir}. Lucky time hint: ${b.luckyTime}. Date: ${b.date}. ` +
      `Write this person's personalized detailed fortune for today as the JSON object.`

    const r = await callLlm(system, user, { maxTokens: 4000, json: true, effort: 'low' })
    if (!r.ok || !r.text) return json({ error: r.error ?? 'empty', detail: r.detail, provider: r.provider, model: r.model }, r.error === 'no_key' ? 500 : 502)

    const detail = parseJson<Record<string, unknown>>(r.text)
    if (!detail) return json({ error: 'parse', provider: r.provider, model: r.model }, 502)
    if (KEYS.some((k) => typeof detail[k] !== 'string' || !(detail[k] as string).trim())) {
      return json({ error: 'shape', provider: r.provider, model: r.model }, 502)
    }
    return json({ detail, provider: r.provider, model: r.model })
  } catch (e) {
    return json({ error: String(e) }, 500)
  }
})
